import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';

function idOf(req: Request): string {
  const id = req.params['budgetMainId'];
  if (typeof id !== 'string' || !/^[0-9]+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '본예산 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

// 현재 상태가 from일 때만 to로 바꾼다. 아니면 409.
function changeStatus(id: string, from: string, to: string, reason: string) {
  return transaction(async (db) => {
    const rows = await db.query(
      'SELECT approval_status AS "approvalStatus" FROM budget_main WHERE budget_main_id = CAST(:id AS bigint) FOR UPDATE',
      { id },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'BUDGET_MAIN_NOT_FOUND', '본예산을 찾을 수 없습니다.');
    }
    if (rows[0].approvalStatus !== from) {
      throw new ApiError(409, 'BUDGET_MAIN_STATUS_CONFLICT', reason);
    }
    await db.execute(
      'UPDATE budget_main SET approval_status = :to, updated_at = now() WHERE budget_main_id = CAST(:id AS bigint)',
      { id, to },
    );
    return { approvalStatus: to };
  });
}

@Controller('api/v1')
export class FnSfr00302Controller {
  @Post('/budget-mains/:budgetMainId/close')
  @HttpCode(200)
  async closeBudgetMain(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return changeStatus(id, '신청', '마감', '신청 상태의 본예산만 마감할 수 있습니다.');
  }

  @Post('/budget-mains/:budgetMainId/cancel-close')
  @HttpCode(200)
  async cancelCloseBudgetMain(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return changeStatus(id, '마감', '마감 취소', '마감 상태의 본예산만 마감 취소할 수 있습니다.');
  }

  @Post('/budget-mains/:budgetMainId/approve')
  @HttpCode(200)
  async approveBudgetMain(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return changeStatus(id, '마감', '승인', '마감 상태의 본예산만 승인할 수 있습니다.');
  }

  @Post('/budget-mains/:budgetMainId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalBudgetMain(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req);
    return changeStatus(id, '승인', '승인 취소', '승인 상태의 본예산만 승인 취소할 수 있습니다.');
  }
}

