import { useState } from 'react';
import { call, Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, RefName, Select } from '../kit';
import type { PageProps, Row } from '../kit';

interface Action {
  label: string;
  path: string;
  from: string;
}

const ACTIONS: Record<string, Action> = {
  close: { label: '마감', path: 'close', from: '신청' },
  cancelClose: { label: '마감 취소', path: 'cancel-close', from: '마감' },
  approve: { label: '승인', path: 'approve', from: '마감' },
  cancelApproval: { label: '승인 취소', path: 'cancel-approval', from: '승인' },
};

// 처리 뒤 바뀐 상태에서 다시 할 수 있는 처리
const NEXT: Record<string, string[]> = {
  '마감': ['cancelClose', 'approve'],
  '승인': ['cancelApproval'],
};

interface Target {
  id: number | string;
  action: string;
  fixed: boolean;
}

export default function FnSfr00302Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [target, setTarget] = useState<Target | null>(null);

  const submit = async () => {
    if (!target) return;
    if (target.id === '' || target.id === undefined) {
      throw new Error('본예산을 선택해 주세요.');
    }
    if (!target.action) {
      throw new Error('처리를 선택해 주세요.');
    }
    const act = ACTIONS[target.action];
    const res = await call<Row>('POST', '/budget-mains/' + target.id + '/' + act.path, role, {});
    setResults((prev) => [
      { budgetMainId: target.id, approvalStatus: res.approvalStatus },
      ...prev.filter((r) => String(r.budgetMainId) !== String(target.id)),
    ]);
    notify('본예산을 ' + act.label + ' 처리했습니다.');
    setTarget(null);
  };

  const columns = [
    {
      key: 'budgetMainId',
      label: '본예산',
      render: (r: Row) => <RefName table="budget_main" role={role} value={r.budgetMainId} />,
    },
    {
      key: 'approvalStatus',
      label: '승인 처리 상태',
      render: (r: Row) => <Badge value={r.approvalStatus} />,
    },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          {(NEXT[String(r.approvalStatus)] ?? []).map((a) => (
            <button
              key={a}
              className="ghost"
              onClick={(e) => {
                e.stopPropagation();
                setTarget({ id: r.budgetMainId as number | string, action: a, fixed: true });
              }}
            >
              {ACTIONS[a].label}
            </button>
          ))}
        </span>
      ),
    },
  ];

  const options: [string, string][] = Object.entries(ACTIONS).map(([k, v]) => [k, v.label]);

  return (
    <div className="doc">
      <section className="box">
        <h2>본예산 마감·승인 처리</h2>
        <Band total={results.length}>
          <button onClick={() => setTarget({ id: '', action: 'close', fixed: false })}>본예산 처리</button>
        </Band>
        <DataTable
          columns={columns}
          rows={results}
          empty="아직 처리한 본예산이 없습니다. 본예산 처리 버튼을 눌러 시작해 주세요."
        />
      </section>
      {target && (
        <Drawer title={'본예산 ' + ACTIONS[target.action].label} onClose={() => setTarget(null)}>
          <Form
            onSubmit={submit}
            submit={ACTIONS[target.action].label + ' 처리'}
            note={'본예산은 "' + ACTIONS[target.action].from + '" 상태일 때만 ' + ACTIONS[target.action].label + ' 처리할 수 있습니다.'}
          >
            <Field label="본예산" required wide>
              {target.fixed ? (
                <RefName table="budget_main" role={role} value={target.id} />
              ) : (
                <LookupSelect
                  table="budget_main"
                  role={role}
                  value={target.id}
                  onChange={(v) => setTarget({ ...target, id: v })}
                  placeholder="본예산 선택"
                />
              )}
            </Field>
            {!target.fixed && (
              <Field label="처리" required wide>
                <Select
                  value={target.action}
                  onChange={(v) => setTarget({ ...target, action: v })}
                  options={options}
                />
              </Field>
            )}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
